rows, columns = 10, 20
n = rows * columns
grid = [[r * columns + c for c in range(columns)] for r in range(rows)]
edges = []
for r in range(rows):
    for c in range(columns):
        if r + 1 < rows:
            edges.append([grid[r][c], grid[r + 1][c]])
        if c + 1 < columns:
            edges.append([grid[r][c], grid[r][c + 1]])
case = {'n': n, 'edges': edges}
expected = grid

